    double iirDriveSampleDR = aw_s->iirDriveSampleDR;
    double iirDriveSampleER = aw_s->iirDriveSampleER;
    double iirDriveSampleFR = aw_s->iirDriveSampleFR;
    bool flip = aw_s->flip;
    int bflip = aw_s->bflip;
    bool WasNegative = aw_s->WasNegative;
    bool SubOctave = aw_s->SubOctave;
    double iirHeadBumpA = aw_s->iirHeadBumpA;
    double iirHeadBumpB = aw_s->iirHeadBumpB;
